/**
 * Whole calendar days from `today` to the due date: 0 on the day itself, -1 the
 * day after it passed.
 *
 * The previous form took the difference between the due date's last second and
 * the current instant and rounded it up, which is not the same question. It
 * read a bid due today as "1 day(s) remain" and one due tomorrow as 2, so a
 * contractor planned against a day they did not have. Worse at the other end:
 * a deadline that expired last night produced a fraction between -1 and 0,
 * which rounds up to 0, so `urgency` never reached `past-due` inside the first
 * 24 hours — the page said "urgent" about a bid that could no longer be filed.
 * An unparseable date produced NaN and printed "NaN day(s) remain"; it is now
 * null, which the page already words as "add a deadline".
 */
export function daysUntilDue(dueDate, today = new Date()) {
  if (!dueDate) return null;
  const due = Date.parse(`${dueDate}T00:00:00`);
  if (Number.isNaN(due)) return null;
  // Both sides collapsed to local midnight before dividing, so a 23- or
  // 25-hour day across a daylight-saving change cannot shift the answer.
  const start = new Date(today).setHours(0, 0, 0, 0);
  return Math.round((due - start) / 86400000);
}

export function assessBid(items, dueDate, today = new Date()) {
  const daysRemaining = daysUntilDue(dueDate, today);
  const rows = items.map((item) => ({
    name: item.name.trim(),
    owner: item.owner.trim(),
    status: item.status,
    note: item.note.trim(),
  }));
  const missing = rows.filter((row) => row.status !== 'ready');
  const blocked = rows.filter((row) => row.status === 'blocked');
  return {
    rows,
    missing,
    blocked,
    ready: rows.length > 0 && missing.length === 0,
    daysRemaining,
    urgency: daysRemaining !== null && daysRemaining < 0 ? 'past-due' : daysRemaining !== null && daysRemaining <= 2 ? 'urgent' : 'normal',
  };
}

/**
 * How the deadline is worded to the user. Zero is the case worth spelling out:
 * "0 day(s) remain" is technically what the count says and reads as though
 * there is no deadline pressure at all, on the one day there is most.
 */
export function deadlineSentence(daysRemaining) {
  if (daysRemaining === null) return 'Add a deadline for urgency context.';
  if (daysRemaining < 0) {
    const days = Math.abs(daysRemaining);
    return `The deadline passed ${days} day${days === 1 ? '' : 's'} ago.`;
  }
  if (daysRemaining === 0) return 'The deadline is today.';
  return `${daysRemaining} day${daysRemaining === 1 ? '' : 's'} remain${daysRemaining === 1 ? 's' : ''}.`;
}

export function markdownReport(result, opportunity, dueDate) {
  const lines = [`# Bid readiness: ${opportunity || 'Untitled opportunity'}`, '', `Due date: ${dueDate || 'Not set'}`, `Result: ${result.ready ? 'All listed items ready' : `${result.missing.length} item(s) need attention`}`, ''];
  for (const row of result.rows) lines.push(`- [${row.status === 'ready' ? 'x' : ' '}] **${row.name}** (${row.status})${row.owner ? ` | owner: ${row.owner}` : ''}${row.note ? ` | ${row.note}` : ''}`);
  lines.push('', 'This is a private working record, not a determination that a bid is complete or compliant. Review the solicitation and confirm requirements with the issuing authority.');
  return lines.join('\n');
}

share.mjs.text:
// Shareable checklist link. The page's own copy already promises "a portable
// handoff" -- today that means a Markdown download, which a subcontractor or
// co-bidder has to open and cannot edit back into this page. "Copy shareable
// link" is the other half of that promise: it puts the opportunity name, the
// due date, and every listed requirement (name, owner, status, note) into the
// URL fragment, so a teammate who opens the link sees and can keep working on
// the exact same checklist rather than retyping it from a PDF export. A
// requirement silently dropped on the way through is a requirement the
// recipient never sees was ever tracked.
//
// The transform is pure: no DOM, no storage, no network, and everything after
// the # never reaches a server or a Referer header. `index.html`'s own
// "Check readiness" handler builds the same `{ name, owner, status, note }`
// shape from the row inputs it reads, so a field added to a row there needs
// only a matching change here, not a second hand-kept list.

/** The two fields the opportunity header carries. */
export const TEXT_FIELD_IDS = Object.freeze(['opportunity']);
export const DATE_FIELD_IDS = Object.freeze(['due']);

/** Mirrors the select options `add()` renders for a requirement row. */
export const ROW_STATUSES = Object.freeze(['ready', 'attention', 'blocked']);

/** Ceiling on the opportunity name -- a sentence, not a solicitation title. */
export const MAX_TEXT = 200;
/** Ceiling on a single requirement's name, owner, or note. */
export const MAX_ROW_TEXT = 120;
/**
 * A checklist this long is far past any real RFP and far below what would
 * strain a browser or a link a chat app is willing to auto-link.
 */
export const MAX_ROWS = 100;

const ROW_SEPARATOR = ',';
const CELL_SEPARATOR = ':';
const ROWS_PARAM = 'items';
const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

// Shape-checked rather than calendar-checked: a link carrying "2099-13-40" is
// passed through to `daysUntilDue`, which already treats an unparseable date
// as "no deadline" the same way a blank field does. This only guards against
// a fragment that is not a date-shaped string at all.
function usableDate(value) {
  return typeof value === 'string' && ISO_DATE_RE.test(value) ? value : null;
}

// Strips ASCII control characters that a requirement name or note should
// never carry and a link must not smuggle through as a stray byte. Written
// as a character-code test rather than a regex literal so no raw control
// byte has to appear anywhere in this source file.
function stripControlChars(value) {
  let out = '';
  for (let i = 0; i < value.length; i += 1) {
    const code = value.charCodeAt(i);
    const tab = 9;
    const newline = 10;
    const carriageReturn = 13;
    const space = 32;
    const del = 127;
    if (code === tab || code === newline || code === carriageReturn || (code >= space && code !== del)) {
      out += value[i];
    }
  }
  return out;
}

function usableText(value, max) {
  if (typeof value !== 'string') return null;
  const clean = stripControlChars(value).trim();
  if (!clean) return null;
  return clean.length > max ? clean.slice(0, max) : clean;
}

// Row cells are URI-encoded so a requirement name or note can contain ":" or
// "," without splitting the row apart, matching the pattern
// tree-service-bid-calculator/share.mjs uses for the same problem.
function encodeCell(value) {
  const raw = stripControlChars(String(value == null ? '' : value)).trim().slice(0, MAX_ROW_TEXT);
  return raw ? encodeURIComponent(raw) : '';
}

function decodeCell(raw) {
  if (!raw) return '';
  try {
    return decodeURIComponent(raw).trim().slice(0, MAX_ROW_TEXT);
  } catch {
    return '';
  }
}

/**
 * Encode the opportunity header and requirement rows as a URL fragment
 * payload (no leading '#').
 *
 * A blank or unusable field is omitted rather than carried as an empty
 * string, and a row with nothing usable in it at all is dropped rather than
 * sent as an empty slot -- either would hand the recipient a value the sender
 * never entered.
 */
export function encodeInputs(inputs) {
  const opportunity = inputs && inputs.opportunity;
  const due = inputs && inputs.due;
  const items = inputs && inputs.items;

  const params = new URLSearchParams();

  const name = usableText(opportunity, MAX_TEXT);
  if (name !== null) params.set('opportunity', name);

  const date = usableDate(due);
  if (date !== null) params.set('due', date);

  const rows = Array.isArray(items) ? items.slice(0, MAX_ROWS) : [];
  const encodedRows = rows
    .map((item) => [
      encodeCell(item && item.name),
      encodeCell(item && item.owner),
      ROW_STATUSES.includes(item && item.status) ? item.status : '',
      encodeCell(item && item.note),
    ].join(CELL_SEPARATOR))
    .filter((row) => row.replaceAll(CELL_SEPARATOR, '') !== '');
  if (encodedRows.length > 0) params.set(ROWS_PARAM, encodedRows.join(ROW_SEPARATOR));

  return params.toString();
}

/**
 * Read a fragment (or query string) back into { opportunity, due, items }.
 *
 * Anything unrecognised, over-long, or not one of the form's own status
 * options is dropped or coerced rather than thrown on, so a truncated or
 * crafted link still opens the page on the fields that survived. A row with
 * no usable name is dropped, matching index.html's own
 * `.filter(item => item.name.trim())` before a row is ever assessed -- a
 * crafted link cannot inject a "requirement" with no name for someone to
 * puzzle over.
 */
export function decodeInputs(source) {
  if (typeof source !== 'string') return {};
  const params = new URLSearchParams(source.replace(/^[?#]/, ''));
  const result = {};

  if (params.has('opportunity')) {
    const name = usableText(params.get('opportunity'), MAX_TEXT);
    if (name !== null) result.opportunity = name;
  }
  if (params.has('due')) {
    const date = usableDate(params.get('due'));
    if (date !== null) result.due = date;
  }
  if (params.has(ROWS_PARAM)) {
    const items = params.get(ROWS_PARAM)
      .split(ROW_SEPARATOR)
      .slice(0, MAX_ROWS)
      .map((row) => {
        const cells = row.split(CELL_SEPARATOR);
        const status = cells[2];
        return {
          name: decodeCell(cells[0]),
          owner: decodeCell(cells[1]),
          status: ROW_STATUSES.includes(status) ? status : 'attention',
          note: decodeCell(cells[3]),
        };
      })
      .filter((item) => item.name.trim() !== '');
    if (items.length > 0) result.items = items;
  }
  return result;
}

usage.mjs.text:
const KEY = 'contractor-bid-readiness-usage';

function trackingDenied() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(event, enabled = true) {
  // The visitor's stored choice, consulted before anything else: the
  // caller passes its own idea of it, and on most pages here that came
  // from a control that had forgotten.
  if (readOptOut()) return;
  if (!enabled || trackingDenied()) return;
  // Usage is optional telemetry, called as the last statement of each click
  // handler in index.html with no try/catch around it there. A blocked, full,
  // or corrupted storage value must never throw out of this call -- an
  // uncaught error here would surface as a broken button even though the
  // readiness check (or the report download) it follows already succeeded.
  try {
    let counts = {};
    try {
      counts = JSON.parse(globalThis.localStorage?.getItem(KEY) || '{}');
      if (!counts || typeof counts !== 'object' || Array.isArray(counts)) counts = {};
    } catch {
      counts = {};
    }
    counts[event] = (Number.isFinite(counts[event]) ? counts[event] : 0) + 1;
    globalThis.localStorage?.setItem(KEY, JSON.stringify(counts));
  } catch {
    // Private browsing and storage quotas are normal browser conditions.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. The recorder above consults it
// directly, so the promise does not depend on a caller remembering to
// pass the choice in.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
